select 'period_name'||'~'||'Code_Combination'||'~'||'ledger_short_name'||'~'||'original_currency_code'||'~'||'functional_currency'||'~'||'je_batch_name'||'~'||'je_batch_description'||'~'||'je_header_name'||'~'||'je_header_description'||'~'||'je_line_num'||'~'||'je_line_description'||'~'||'entered_amount'||'~'||'accounted_amount'||'~'||'effective_date'||'~'||'POSTED_STATUS'||'~'||'posted_date'||'~'||'attribute1'||'~'|| 'attribute2'||'~'||'attribute3'||'~'||'attribute4'||'~'||'attribute5'||'~'|| 'attribute6'||'~'||'attribute7'||'~'|| 'attribute8'||'~'||'attribute9'||'~'|| 'attribute10'||'~'||'attribute11'||'~'|| 'attribute12'||'~'||'attribute13'||'~'|| 'attribute14'||'~'||'attribute15'||'~'|| 'attribute16'||'~'||'attribute17'||'~'|| 'attribute18'||'~'||'attribute19'||'~'|| 'attribute20' JE_DETAILS_BATCH
FROM dual
UNION ALL
select gjh.period_name||','||segment1||'.'||segment2||'.'||segment3||'.'||segment4||'.'||segment5||'.'||segment6||'.'||segment7||'.'||segment8||'.'||segment9||'.'||Segment10||'.'||Segment11||','||led.name||','||gjl.currency_code||','||led.currency_code||','||REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(gjb.name,',',';'), CHR(13), ' '), CHR(10), ' '),CHR(9), ' '),CHR(160),' ')||','||REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(gjb.description,',',';'), CHR(13), ' '), CHR(10), ' '),CHR(9), ' '),CHR(160),' ')||','||REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(gjh.name,',',';'), CHR(13), ' '), CHR(10), ' '),CHR(9), ' '),CHR(160),' ')||','||REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(gjh.description,',',';'), CHR(13), ' '), CHR(10), ' '),CHR(9), ' '),CHR(160),' ')||','||TO_CHAR(gjl.je_line_num)||','||REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(gjl.description,',',';'), CHR(13), ' '), CHR(10), ' '),CHR(9), ' '),CHR(160),' ')||','||TO_CHAR(NVL(entered_dr,0) - NVL(entered_cr,0))||','||TO_CHAR(NVL(accounted_dr,0) - NVL(accounted_cr,0))||','||TO_CHAR(gjl.effective_date,'YYYYMMDD')||','||DECODE(gjh.status,'P','JE Posted','JE Not Posted')||','||TO_CHAR(gjh.posted_date,'YYYYMMDD')||','||gjl.attribute1||','|| gjl.attribute2||','||gjl.attribute3||','|| gjl.attribute4||','||gjl.attribute5||','|| gjl.attribute6||','||gjl.attribute7||','|| gjl.attribute8||','||gjl.attribute9||','|| gjl.attribute10||','||gjl.attribute11||','|| gjl.attribute12||','||gjl.attribute13||','|| gjl.attribute14||','||gjl.attribute15||','|| gjl.attribute16||','||gjl.attribute17||','|| gjl.attribute18||','||gjl.attribute19||','|| gjl.attribute20 
 FROM  gl_je_headers        gjh,
          gl_je_lines 	       gjl,
          gl_je_batches        gjb,
          gl_code_combinations glc,
          gl_ledgers           led 
WHERE gjh.je_header_id             = gjl.je_header_id
     AND  gjb.je_batch_id              = gjh.je_batch_id
     AND  gjl.code_combination_id      = glc.code_combination_id
     AND  gjh.ledger_id                = led.ledger_id
     AND  gjb.name = 'CCLFGL.APCAND.CCLJEES.000003 CCL_AP_INTERFACE A 771 51514 N'